import collections, hashlib, json, re

BLOC_EXIG = re.compile(
    r'<div id="exig-[^"]+">\s*<p><strong><code>(EXIG-[A-Z0-9]{3}-\d{2})</code> · '
    r'((?:NE )?(?:DOIT|DEVRAIT|PEUT)(?: PAS)?(?: · (?:NE )?(?:DOIT|DEVRAIT|PEUT)(?: PAS)?)*)'
    r'</strong></p>\s*<p><strong>(.*?)</strong></p>',
    re.S,
)


def _expand_exig_code_block(m):
    txt = m.group(1)
    if 'EXIG-' not in txt:
        return m.group(0)
    out = []
    cur_dom = None
    cur_num = None
    for tok in re.finditer(
        r'EXIG-([A-Z0-9]{3})-(\d{2})|(\bà\s*(?:EXIG-([A-Z0-9]{3})-|-)(\d{2}))|(?:,\s*|et\s*)-(\d{2})',
        txt,
    ):
        if tok.group(1):
            cur_dom = tok.group(1)
            cur_num = int(tok.group(2))
            code = f'EXIG-{cur_dom}-{cur_num:02d}'
            if code not in out:
                out.append(code)
        elif tok.group(3):
            dom = tok.group(4) or cur_dom
            end_num = int(tok.group(5))
            for k in range(cur_num + 1, end_num + 1):
                code = f'EXIG-{dom}-{k:02d}'
                if code not in out:
                    out.append(code)
            cur_num = end_num
        elif tok.group(6):
            cur_num = int(tok.group(6))
            code = f'EXIG-{cur_dom}-{cur_num:02d}'
            if code not in out:
                out.append(code)
    return '<code>' + ', '.join(out) + '</code>'


def transformer(s: str) -> str:
    # 1. Extraire les 287 exigences du corps corrigé
    i_ann = s.index('<h2>A Grille d’homologation</h2>')
    corps = s[:i_ann]
    blocs = BLOC_EXIG.findall(corps)
    nb_divs = corps.count('<div id="exig-')
    assert len(blocs) == nb_divs == 287, f'registre : {nb_divs} divs EXIG, {len(blocs)} blocs lisibles (attendu 287)'
    doublons = [k for k, n in collections.Counter(b[0] for b in blocs).items() if n > 1]
    assert not doublons, f'registre : identifiants en double {doublons}'

    # 2. Vérifier et développer la grille d’homologation de l’annexe A (couverture des 287 EXIG)
    j_ann_a = s.index('<h2>B Gabarit de fiche d’agent</h2>', i_ann)
    sec_a = s[i_ann:j_ann_a]
    sec_a_expanded = re.sub(r'<code>([^<]*EXIG-[^<]*)</code>', _expand_exig_code_block, sec_a)
    couverts = set(re.findall(r'EXIG-[A-Z0-9]{3}-\d{2}', sec_a_expanded))
    attendus = {b[0] for b in blocs}
    manquants = sorted(attendus - couverts)
    assert not manquants, f'Annexe A : exigences manquantes sur les 287 : {manquants}'
    s = s[:i_ann] + sec_a_expanded + s[j_ann_a:]

    # 3. Régénérer le registre de l’annexe D à partir des 287 exigences du corps corrigé
    i_d = s.index('<h2>D Registre des exigences</h2>')
    j_d = s.index('<h2>E ', i_d)
    d_sec = s[i_d:j_d]
    t0 = d_sec.index('<tbody>') + len('<tbody>')
    t1 = d_sec.rindex('</tbody>')
    ancien_tbody = d_sec[t0:t1]
    lignes = ''.join(
        f'<tr><td><code>{x}</code></td><td><strong>{f}</strong></td><td>{t}</td></tr>'
        for x, f, t in blocs
    )
    d_sec = d_sec[:t0] + lignes + d_sec[t1:]
    s = s[:i_d] + d_sec + s[j_d:]

    # 4. Vérifier / recalculer l’empreinte SHA-256 / JCS de l’enregistrement d’audit C.8
    i_c8 = s.index('<h3>C.8 Enregistrement d’audit</h3>')
    j_c8 = s.index('<h2>D Registre des exigences</h2>', i_c8)
    c8_sec = s[i_c8:j_c8]
    m_json = re.search(r'<pre><code>(\{.*?\})</code></pre>', c8_sec, flags=re.S)
    if m_json:
        obj = json.loads(m_json.group(1))
        jcs_bytes = json.dumps(
            obj['enregistrement'], ensure_ascii=False, sort_keys=True, separators=(',', ':')
        ).encode('utf-8')
        emp = 'sha256:' + hashlib.sha256(jcs_bytes).hexdigest()
        c8_sec = re.sub(r'"empreinte": "sha256:[0-9a-f]{64}"', f'"empreinte": "{emp}"', c8_sec)
        s = s[:i_c8] + c8_sec + s[j_c8:]

    return s, [ancien_tbody]
